import { db } from "@drizzle-run/runtime/context";
import { asc } from "drizzle-orm";

import { posts } from "./schema";

const first = await db.select().from(posts).orderBy(asc(posts.createdAt), asc(posts.id)).limit(2);
$.display("First page before insert", first);

await db.insert(posts).values({ id: 7, title: "Earlier arrival", createdAt: "2025-12-31T09:00:00.000Z" });
const second = await db.select().from(posts).orderBy(asc(posts.createdAt), asc(posts.id)).limit(2).offset(2);
$.display("Offset page after insert", second);

import { db } from "@drizzle-run/runtime/context";
import { asc, gt } from "drizzle-orm";

import { posts } from "./schema";

const first = await db.select().from(posts).orderBy(asc(posts.createdAt), asc(posts.id)).limit(2);
const last = first.at(-1);
$.display("First page", first);

if (last) {
  const second = await db.select().from(posts)
    .where(gt(posts.createdAt, last.createdAt))
    .orderBy(asc(posts.createdAt), asc(posts.id)).limit(2);
  $.display("Timestamp-only cursor skips a tie", second);
}

import { getNextPage } from "./pagination";

const first = await getNextPage();
$.display("Cursor page 1", first);

if (first.nextCursor) {
  const second = await getNextPage({ after: first.nextCursor });
  $.display("Cursor page 2", second);

  if (second.nextCursor) {
    $.display("Cursor page 3", await getNextPage({ after: second.nextCursor }));
  }
}
